#[test]
fn recognized_transfer_fixture_renders_the_pinned_display_lines() {
    let framed: Vec<u8> = decode_hex(RECOGNIZED_TRANSFER_FRAME_HEX);
    let view = build_clear_signing_view(
        &framed,
        &DeviceSigningProfile::V1,
        &DEVNET_ASSET_TRANSFER_POLICY,
    )
    .unwrap();

    assert_eq!(view.lines(), RECOGNIZED_TRANSFER_LINES);
}
